INSERT OR IGNORE INTO aiedu_documents (id, doc_type, subject, title, content, source, tags) VALUES
('seed-cp-informatika', 'cp', 'Informatika', 'Capaian Pembelajaran Informatika Fase E (Kelas X)',
'# Capaian Pembelajaran Informatika — Fase E (Kelas X)\n\n## Rasional\nInformatika adalah disiplin ilmu yang mengkaji konsep, prinsip, dan praktik komputasi. Pada fase E, peserta didik memahami dasar-dasar berpikir komputasional, sistem komputer, jaringan, dan dampak sosial informatika.\n\n## Elemen & CP\n| Elemen | Capaian Pembelajaran |\n|---|---|\n| Berpikir Komputasional (BK) | Peserta didik mampu menerapkan strategi algoritmik standar untuk menghasilkan solusi persoalan dalam berbagai bidang dengan memanfaatkan data dan teknologi |\n| Teknologi Informasi & Komunikasi (TIK) | Peserta didik mampu memahami dan menerapkan praktik baik penggunaan teknologi informasi dan komunikasi dalam kehidupan sehari-hari |\n| Sistem Komputer (SK) | Peserta didik mampu memahami komponen sistem komputer, perangkat keras, perangkat lunak, dan interaksi antar komponen |\n| Jaringan Komputer & Internet (JKI) | Peserta didik mampu memahami arsitektur jaringan komputer, internet, dan keamanan siber dasar |\n| Analisis Data (AD) | Peserta didik mampu memahami dan melakukan analisis data sederhana menggunakan perangkat lunak spreadsheet |\n| Algoritma & Pemrograman (AP) | Peserta didik mampu menulis program prosedural sederhana dengan bahasa pemrograman tertentu |\n| Dampak Sosial Informatika (DSI) | Peserta didik mampu menganalisis dampak positif dan negatif teknologi informasi dalam kehidupan |\n| Praktik Lintas Bidang (PLB) | Peserta didik mampu menghasilkan karya kreatif berbasis komputasi dalam proyek kolaboratif |\n\n## Alokasi\nFase E umumnya 3-4 JP per minggu.',
'seed', '["fase-e","kelas-x"]'),
('seed-atp-informatika', 'atp', 'Informatika', 'Contoh ATP Informatika Fase E',
'# Alur Tujuan Pembelajaran Informatika — Fase E\n\n## Identitas\n- Mapel: Informatika\n- Fase: E (Kelas X)\n- Semester: 1-2\n\n## Capaian Pembelajaran\nMengacu pada CP Informatika Fase E (lihat dokumen CP).\n\n## Tabel ATP\n| Elemen | Tujuan Pembelajaran | Indikator Ketercapaian | Alokasi |\n|---|---|---|---|\n| BK | 10.1 Menerapkan dekomposisi untuk memecah masalah kompleks | Mampu mengurai masalah besar menjadi sub-masalah kecil | 4 JP |\n| BK | 10.2 Mengidentifikasi pola dalam deret dan struktur data sederhana | Mampu menemukan pola berulang dalam persoalan | 4 JP |\n| TIK | 10.3 Menggunakan aplikasi perkantoran untuk kolaborasi | Mampu membuat dokumen bersama secara daring | 3 JP |\n| SK | 10.4 Menjelaskan fungsi perangkat keras dan lunak | Mampu mengidentifikasi komponen komputer dan fungsinya | 4 JP |\n| JKI | 10.5 Memahami dasar jaringan komputer dan internet | Mampu menjelaskan cara kerja internet dan protokol dasar | 4 JP |\n| AD | 10.6 Mengolah data dengan spreadsheet | Mampu membuat tabel, grafik, dan rumus dasar | 6 JP |\n| AP | 10.7 Menulis program prosedural sederhana | Mampu membuat program input-proses-output | 12 JP |\n| DSI | 10.8 Menganalisis dampak sosial teknologi | Mampu mempresentasikan dampak positif-negatif media sosial | 4 JP |\n\n## Catatan\n- Urutan TP: dari konsep ke praktik, sederhana ke kompleks.\n- Asesmen formatif dilakukan setiap akhir tujuan pembelajaran.',
'seed', '["fase-e","contoh"]'),
('seed-modul-informatika', 'modul_ajar', 'Informatika', 'Modul Ajar Contoh: Pengenalan Algoritma & Pemrograman (Kelas X)',
'# Modul Ajar — Pengenalan Algoritma & Pemrograman\n\n## Informasi Umum\n| Aspek | Detail |\n|---|---|\n| Mapel | Informatika |\n| Fase/Kelas | E / X |\n| Semester | 1 |\n| Alokasi | 4 JP (2 pertemuan) |\n| Model | Problem Based Learning |\n| Profil Pelajar | Bernalar kritis, Kreatif, Mandiri |\n\n## Kompetensi Awal\nPeserta didik mengenal penggunaan komputer dasar.\n\n## Tujuan Pembelajaran\n1. Menjelaskan konsep algoritma dalam kehidupan sehari-hari\n2. Menyusun algoritma sederhana dalam bentuk flowchart\n3. Menerjemahkan flowchart ke program prosedural sederhana\n\n## Pertanyaan Pemantik\n- "Bagaimana cara membuat resep masakan menjadi algoritma?"\n- "Apa bedanya manusia dengan komputer dalam menjalankan instruksi?"\n\n## Kegiatan Pembelajaran\n\n### Pertemuan 1 (2 JP)\n**Pendahuluan (15 menit)**: Apersepsi, pertanyaan pemantik, tujuan pembelajaran.\n**Inti (60 menit)**:\n- Eksplorasi: peserta didik menyusun langkah membuat teh manis (dekomposisi)\n- Elaborasi: guru memperkenalkan flowchart, peserta didik mengubah langkah menjadi flowchart\n- Konfirmasi: diskusi kelas, umpan balik\n**Penutup (15 menit)**: Refleksi, rangkuman, tugas mandiri.\n\n### Pertemuan 2 (2 JP)\n**Pendahuluan (15 menit)**: Review flowchart.\n**Inti (60 menit)**:\n- Demo: menerjemahkan flowchart ke program Python/Scratch\n- Praktik: peserta didik menulis program sederhana (input nama, output sapaan)\n**Penutup (15 menit)**: Presentasi hasil, asesmen formatif.\n\n## Asesmen\n- **Diagnostik**: kuis awal konsep algoritma\n- **Formatif**: observasi praktik + LKPD\n- **Sumatif**: proyek flowchart & program sederhana\n\n## Pengayaan\nPeserta didik cepat: buat program kalkulator sederhana.\n\n## Remedial\nPeserta didik lambat: bimbingan flowchart dengan contoh tambahan.',
'seed', '["contoh","kelas-x"]'),
('seed-buku-guru', 'buku_guru', 'Informatika', 'Panduan Buku Guru: Informatika Kelas X',
'# Panduan Penggunaan Buku Guru — Informatika Kelas X\n\n## Tujuan Buku Guru\nMembantu guru merencanakan, melaksanakan, dan mengevaluasi pembelajaran Informatika sesuai Kurikulum Merdeka.\n\n## Struktur Buku\n1. **Bab 1**: Berpikir Komputasional\n2. **Bab 2**: Teknologi Informasi & Komunikasi\n3. **Bab 3**: Sistem Komputer\n4. **Bab 4**: Jaringan Komputer & Internet\n5. **Bab 5**: Analisis Data\n6. **Bab 6**: Algoritma & Pemrograman\n7. **Bab 7**: Dampak Sosial Informatika\n8. **Bab 8**: Proyek Lintas Bidang\n\n## Tips Penggunaan\n- Gunakan pendekatan student-centered learning\n- Manfaatkan LKPD di setiap bab untuk aktivitas kelompok\n- Asesmen formatif setiap akhir bab\n- Diferensiasi: sesuaikan tugas dengan kemampuan peserta didik\n- Integrasikan profil pelajar Pancasila di setiap kegiatan',
'seed', '["panduan"]'),
('seed-buku-siswa', 'buku_siswa', 'Informatika', 'Ringkasan Buku Siswa: Informatika Kelas X',
'# Buku Siswa — Informatika Kelas X\n\n## Bab 1: Berpikir Komputasional\nDekomposisi, pengenalan pola, abstraksi, algoritma.\n\n## Bab 2: Teknologi Informasi & Komunikasi\nPerangkat lunak perkantoran, kolaborasi daring, etika digital.\n\n## Bab 3: Sistem Komputer\nPerangkat keras, perangkat lunak, sistem operasi, interaksi antar komponen.\n\n## Bab 4: Jaringan Komputer & Internet\nLAN/WAN, protokol, topologi, keamanan siber dasar.\n\n## Bab 5: Analisis Data\nSpreadsheet, formula, grafik, interpretasi data.\n\n## Bab 6: Algoritma & Pemrograman\nFlowchart, variabel, percabangan, perulangan, fungsi sederhana.\n\n## Bab 7: Dampak Sosial Informatika\nLiterasi digital, keamanan data pribadi, etika media sosial.\n\n## Bab 8: Proyek Lintas Bidang\nProyek kolaboratif: aplikasi sederhana atau karya digital.',
'seed', '["ringkasan"]'),
('seed-panduan-asesmen', 'panduan_asesmen', 'Umum', 'Panduan Asesmen Kurikulum Merdeka',
'# Panduan Asesmen Kurikulum Merdeka\n\n## Prinsip Asesmen\n1. Asesmen adalah bagian terpadu dari pembelajaran\n2. Dirancang sesuai tujuan pembelajaran\n3. Menggunakan berbagai bentuk dan instrumen\n4. Memberikan umpan balik untuk perbaikan\n5. Adil, valid, dan reliabel\n\n## Jenis Asesmen\n| Jenis | Fungsi | Contoh |\n|---|---|---|\n| Diagnostik | Memetakan kesiapan belajar | Kuis awal, pretest |\n| Formatif | Memantau proses belajar | Observasi, kuis, diskusi |\n| Sumatif | Mengukur pencapaian akhir | Ujian, proyek, portofolio |\n\n## Instrumen\n- Rubrik penilaian (4 skala)\n- Lembar observasi\n- Tes tulis (PG, esai)\n- Portofolio karya\n\n## Pelaporan\n- Deskripsi capaian kompetensi\n- Predikat: A (90-100), B (80-89), C (70-79), D (<70)\n- Refleksi dan tindak lanjut',
'seed', '["asesmen"]'),
('seed-panduan-projek', 'panduan_projek', 'Umum', 'Panduan Projek Penguatan Profil Pelajar Pancasila (P5)',
'# Panduan Projek P5\n\n## Konsep\nProjek Penguatan Profil Pelajar Pancasila (P5) adalah pembelajaran lintas disiplin untuk mengamati dan memikirkan solusi isu nyata.\n\n## Dimensi Profil Pelajar Pancasila\n1. Beriman, bertakwa, dan berakhlak mulia\n2. Berkebinekaan global\n3. Bergotong royong\n4. Mandiri\n5. Bernalar kritis\n6. Kreatif\n\n## Tahapan Projek\n| Tahap | Aktivitas |\n|---|---|\n| Pengenalan | Mengenalkan tema & isu |\n| Kontekstualisasi | Mengaitkan dengan konteks lokal |\n| Aksi | Merancang & melaksanakan aksi |\n| Refleksi | Refleksi & tindak lanjut |\n\n## Tema Projek\n- Gaya Hidup Berkelanjutan\n- Kearifan Lokal\n- Kewirausahaan\n- Suara Demokrasi\n- Berekayasa & Berteknologi\n\n## Contoh Kegiatan\nProjek "Berekayasa & Berteknologi": peserta didik merancang solusi digital sederhana untuk masalah sekolah.',
'seed', '["p5","projek"]');
